export default function App() {
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState(null);
  const [oficinas, setOficinas] = useState([]);
  const [ambientes, setAmbientes] = useState([]);
  const [inscricoes, setInscricoes] = useState([]);
  const [view, setView] = useState("home");
  const [professorNome, setProfessorNome] = useState("");
  const [toast, setToast] = useState(null);
  const [adminUnlocked, setAdminUnlocked] = useState(
    () => sessionStorage.getItem("literarena_admin_unlocked") === "1"
  );

  function unlockAdmin() {
    sessionStorage.setItem("literarena_admin_unlocked", "1");
    setAdminUnlocked(true);
  }

  useEffect(() => { loadAll(); }, []);

  function flash(msg, isError = false) {
    setToast({ msg, isError });
    setTimeout(() => setToast(null), isError ? 7000 : 2600);
  }

  async function loadAll() {
    setLoading(true);
    setErr(null);
    try {
      const [o, a, i] = await Promise.all([
        safeGet(KEYS.OFICINAS), safeGet(KEYS.AMBIENTES), safeGet(KEYS.INSCRICOES),
      ]);
      setOficinas(o || []);
      setInscricoes(i || []);
      if (a && a.length > 0) {
        setAmbientes(a);
      } else {
        setAmbientes(DEFAULT_AMBIENTES);
        try {
          await storage.set(KEYS.AMBIENTES, JSON.stringify(DEFAULT_AMBIENTES), []);
        } catch {
          // se falhar, a lista padrão ainda fica visível nesta sessão
        }
      }
    } catch (e) {
      setErr("Não foi possível carregar os dados. Tente recarregar.");
    } finally {
      setLoading(false);
    }
  }

  async function safeGet(key) {
    try {
      const res = await storage.get(key, true);
      return res ? JSON.parse(res.value) : [];
    } catch {
      return [];
    }
  }

  // Retorna true se realmente salvou. Se falhar, desfaz a mudança otimista
  // (a tela nunca mostra algo como salvo quando na verdade não foi).
  async function persist(key, value, setter, previous) {
    setter(value);
    try {
      await storage.set(key, JSON.stringify(value), previous);
      return true;
    } catch (e) {
      setter(previous);
      flash("Não foi possível salvar — tente de novo. Se persistir, avise a coordenação.", true);
      return false;
    }
  }

  const saveOficinas = (v) => persist(KEYS.OFICINAS, v, setOficinas, oficinas);
  const saveAmbientes = (v) => persist(KEYS.AMBIENTES, v, setAmbientes, ambientes);
  const saveInscricoes = (v) => persist(KEYS.INSCRICOES, v, setInscricoes, inscricoes);

  const vagasOcupadas = (oficinaId, grupo) =>
    inscricoes.filter((i) => i.oficinaId === oficinaId && (!grupo || grupoPorSerie(i.serie) === grupo)).length;

  if (loading) {
    return (
      <div className="min-h-[500px] flex items-center justify-center bg-indigo-950 font-sans">
        <div className="text-amber-300 flex items-center gap-2">
          <RefreshCw className="w-5 h-5 animate-spin" /> Carregando o LiterArena…
        </div>
      </div>
    );
  }

  return (
    <div className="min-h-[600px] bg-stone-50 font-sans text-slate-800">
      {toast && (
        <div
          className={`fixed top-3 left-1/2 -translate-x-1/2 z-50 text-sm px-4 py-2.5 rounded-2xl shadow-lg border max-w-[90vw] text-center pointer-events-none ${
            toast.isError
              ? "bg-rose-600 text-white border-rose-800 font-semibold"
              : "bg-indigo-950 text-amber-200 border-indigo-800"
          }`}
        >
          {toast.msg}
        </div>
      )}
      {err && (
        <div className="bg-rose-100 text-rose-800 text-sm px-4 py-2 text-center">{err}</div>
      )}

      {view === "home" && <Home onNav={setView} totals={{ oficinas: oficinas.length, professores: new Set(oficinas.map(o => o.professor.toLowerCase())).size, inscricoes: inscricoes.length }} />}

      {view === "professor" && (
        <ProfessorPortal
          onBack={() => setView("home")}
          professorNome={professorNome}
          setProfessorNome={setProfessorNome}
          oficinas={oficinas}
          saveOficinas={saveOficinas}
          ambientes={ambientes}
          inscricoes={inscricoes}
          flash={flash}
        />
      )}

      {view === "admin" && !adminUnlocked && (
        <AdminLogin onBack={() => setView("home")} onUnlock={unlockAdmin} />
      )}

      {view === "admin" && adminUnlocked && (
        <AdminPortal
          onBack={() => setView("home")}
          oficinas={oficinas}
          saveOficinas={saveOficinas}
          ambientes={ambientes}
          saveAmbientes={saveAmbientes}
          inscricoes={inscricoes}
          saveInscricoes={saveInscricoes}
          vagasOcupadas={vagasOcupadas}
          flash={flash}
        />
      )}

      {view === "aluno" && (
        <AlunoPortal
          onBack={() => setView("home")}
          oficinas={oficinas}
          inscricoes={inscricoes}
          saveInscricoes={saveInscricoes}
          vagasOcupadas={vagasOcupadas}
          flash={flash}
        />
      )}
    </div>
  );
}

