/* ---------------- PROFESSOR ---------------- */
function ProfessorLogin({ onBack, onLogin }) {
  const [nome, setNome] = useState("");
  const [senha, setSenha] = useState("");
  const [confirmarSenha, setConfirmarSenha] = useState("");
  const [etapa, setEtapa] = useState("nome"); // nome | entrar | criar
  const [erro, setErro] = useState("");
  const [carregando, setCarregando] = useState(false);

  async function continuarComNome() {
    if (!nome.trim()) return;
    setErro("");
    setCarregando(true);
    try {
      const professor = await buscarProfessor(nome);
      setEtapa(professor ? "entrar" : "criar");
    } catch {
      setErro("Não foi possível verificar seu cadastro. Tente de novo.");
    } finally {
      setCarregando(false);
    }
  }

  async function entrar() {
    if (!senha) return;
    setErro("");
    setCarregando(true);
    try {
      const ok = await senhaValida(nome, senha);
      if (ok) onLogin(nome.trim());
      else setErro("Senha incorreta.");
    } catch {
      setErro("Não foi possível entrar. Tente de novo.");
    } finally {
      setCarregando(false);
    }
  }

  async function criarConta() {
    if (senha.length < 6) { setErro("A senha precisa ter pelo menos 6 caracteres."); return; }
    if (senha !== confirmarSenha) { setErro("As senhas não coincidem."); return; }
    setErro("");
    setCarregando(true);
    try {
      await criarProfessor(nome, senha);
      onLogin(nome.trim());
    } catch (e) {
      if (e.message === "CONTA_JA_EXISTE") {
        setEtapa("entrar");
        setSenha("");
        setErro("Essa conta já existe. Digite sua senha.");
      } else {
        setErro("Não foi possível criar sua senha. Tente de novo.");
      }
    } finally {
      setCarregando(false);
    }
  }

  function trocarNome() {
    setEtapa("nome");
    setSenha("");
    setConfirmarSenha("");
    setErro("");
  }

  return (
    <div>
      <BackBar onBack={onBack} title="Portal do Professor" />
      <div className="max-w-sm mx-auto px-6 py-16 text-center">
        <GraduationCap className="w-10 h-10 mx-auto text-indigo-700 mb-3" />

        {etapa === "nome" && (
          <>
            <p className="text-slate-600 mb-4">Selecione seu nome para cadastrar ou consultar suas oficinas.</p>
            <select
              value={nome}
              onChange={(e) => setNome(e.target.value)}
              autoFocus
              className="input mb-3"
            >
              <option value="">Selecione…</option>
              {PROFESSORES_LISTA.map((p) => <option key={p} value={p}>{p}</option>)}
            </select>
            {erro && <p className="text-rose-600 text-sm mb-3">{erro}</p>}
            <button
              disabled={!nome.trim() || carregando}
              onClick={continuarComNome}
              className="w-full bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
            >
              {carregando ? "Verificando…" : "Continuar"}
            </button>
          </>
        )}

        {etapa === "entrar" && (
          <>
            <p className="text-slate-600 mb-1">Olá, <strong>{nome.trim()}</strong>.</p>
            <p className="text-slate-500 text-sm mb-4">Digite sua senha para entrar.</p>
            <input
              type="password"
              value={senha}
              onChange={(e) => { setSenha(e.target.value); setErro(""); }}
              onKeyDown={(e) => e.key === "Enter" && entrar()}
              placeholder="Senha"
              autoFocus
              className="input mb-3"
            />
            {erro && <p className="text-rose-600 text-sm mb-3">{erro}</p>}
            <button
              disabled={!senha || carregando}
              onClick={entrar}
              className="w-full bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
            >
              {carregando ? "Entrando…" : "Entrar"}
            </button>
            <button onClick={trocarNome} className="mt-3 text-xs text-slate-400 hover:text-slate-600">
              Não é você? Trocar nome
            </button>
          </>
        )}

        {etapa === "criar" && (
          <>
            <p className="text-slate-600 mb-1">Olá, <strong>{nome.trim()}</strong>! Primeiro acesso.</p>
            <p className="text-slate-500 text-sm mb-4">Crie uma senha para acessar suas oficinas sempre com esse nome.</p>
            <input
              type="password"
              value={senha}
              onChange={(e) => { setSenha(e.target.value); setErro(""); }}
              placeholder="Crie uma senha (mín. 6 caracteres)"
              autoFocus
              className="input mb-3"
            />
            <input
              type="password"
              value={confirmarSenha}
              onChange={(e) => { setConfirmarSenha(e.target.value); setErro(""); }}
              onKeyDown={(e) => e.key === "Enter" && criarConta()}
              placeholder="Confirme a senha"
              className="input mb-3"
            />
            {erro && <p className="text-rose-600 text-sm mb-3">{erro}</p>}
            <button
              disabled={!senha || !confirmarSenha || carregando}
              onClick={criarConta}
              className="w-full bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
            >
              {carregando ? "Criando…" : "Criar senha e continuar"}
            </button>
            <button onClick={trocarNome} className="mt-3 text-xs text-slate-400 hover:text-slate-600">
              Não é você? Trocar nome
            </button>
          </>
        )}

        <style>{`.input { width:100%; border:1px solid #d6d3d1; border-radius:0.5rem; padding:0.6rem 0.9rem; font-size:0.9rem; } .input:focus { outline:none; box-shadow:0 0 0 2px #fbbf24; }`}</style>
      </div>
    </div>
  );
}

function ProfessorPortal({ onBack, professorNome, setProfessorNome, oficinas, saveOficinas, ambientes, inscricoes, flash }) {
  const [editing, setEditing] = useState(null);

  if (PROFESSOR_LOGIN_BLOQUEADO) {
    return (
      <div>
        <BackBar onBack={onBack} title="Portal do Professor" />
        <div className="max-w-sm mx-auto px-6 py-16 text-center">
          <AlertTriangle className="w-10 h-10 mx-auto text-amber-500 mb-3" />
          <p className="text-slate-700 font-semibold">Sistema está sendo atualizado.</p>
          <p className="text-slate-500 text-sm mt-1">Tente novamente mais tarde.</p>
        </div>
      </div>
    );
  }

  if (!professorNome) {
    return <ProfessorLogin onBack={onBack} onLogin={setProfessorNome} />;
  }

  const minhas = oficinas.filter((o) => o.professor.toLowerCase() === professorNome.toLowerCase());
  const pendentesDeVoce = minhas.filter(
    (o) => !o.tituloAprovado || !o.descricaoAprovado || (o.ambienteAlocado && !o.ambienteAprovado)
  );

  return (
    <div>
      <BackBar onBack={onBack} title="Portal do Professor" />
      <div className="max-w-2xl mx-auto px-5 py-6">
        <div className="flex items-center justify-between mb-5">
          <p className="text-sm text-slate-500">Olá, <span className="font-semibold text-slate-800">{professorNome}</span></p>
          <button onClick={() => setProfessorNome("")} className="text-xs text-slate-400 hover:text-slate-600 flex items-center gap-1"><LogOut className="w-3.5 h-3.5" /> trocar</button>
        </div>

        {!editing && pendentesDeVoce.length > 0 && (
          <div className="bg-rose-50 border border-rose-300 rounded-xl px-4 py-3 mb-5 flex items-center gap-2">
            <AlertTriangle className="w-5 h-5 text-rose-600 shrink-0" />
            <p className="text-sm text-rose-800 font-semibold">
              {pendentesDeVoce.length === 1 ? "Você tem 1 oficina" : `Você tem ${pendentesDeVoce.length} oficinas`} aguardando sua confirmação.
            </p>
          </div>
        )}

        <h3 className="font-serif font-bold text-indigo-950 mb-4">Minhas Oficinas ({minhas.length})</h3>

        {editing ? (
          <OficinaForm
            professorNome={professorNome}
            initial={editing}
            ambientes={ambientes}
            onCancel={() => setEditing(null)}
            onSubmit={async (data) => {
              const ok = await saveOficinas(oficinas.map((o) => (o.id === editing.id ? { ...o, ...data, status: "pendente" } : o)));
              if (ok) {
                flash("Obrigado pelo envio! Em breve informaremos sobre as próximas etapas e iniciaremos a divulgação.");
                setEditing(null);
              }
              return ok;
            }}
          />
        ) : (
          <div className="space-y-3">
            {minhas.length === 0 && <p className="text-sm text-slate-400 text-center py-10">Nenhuma oficina cadastrada pela coordenação ainda.</p>}
            {minhas.map((o) => {
              const precisaAcao = precisaConfirmacaoDoProfessor(o);
              const editavel = o.status === "pendente" || o.status === "ajustes";
              const inscritos67 = inscricoes.filter((i) => i.oficinaId === o.id && grupoPorSerie(i.serie) === "67");
              const inscritos89 = inscricoes.filter((i) => i.oficinaId === o.id && grupoPorSerie(i.serie) === "89");
              return (
              <div
                key={o.id}
                onClick={editavel ? () => setEditing(o) : undefined}
                className={`border rounded-xl p-4 bg-white ${precisaAcao ? "border-rose-300" : "border-stone-200"} ${editavel ? "cursor-pointer hover:border-indigo-300" : ""}`}
              >
                <div className="flex items-start justify-between gap-3">
                  <div>
                    <h3 className="font-serif font-bold text-indigo-950">{o.nome}</h3>
                    <p className="text-sm text-slate-500 mt-0.5">{o.descricao}</p>
                  </div>
                  {precisaAcao ? (
                    <span className="inline-flex items-center gap-1 text-xs font-bold px-2.5 py-1 rounded-full border bg-rose-100 text-rose-800 border-rose-300 shrink-0 whitespace-nowrap">
                      <AlertTriangle className="w-3.5 h-3.5" /> Falta você confirmar
                    </span>
                  ) : o.status === "pendente" ? (
                    <span className="inline-flex items-center gap-1 text-xs font-bold px-2.5 py-1 rounded-full border bg-blue-100 text-blue-800 border-blue-300 shrink-0 whitespace-nowrap">
                      <CheckCircle2 className="w-3.5 h-3.5" /> Oficina confirmada
                    </span>
                  ) : (
                    <StatusBadge status={o.status} />
                  )}
                </div>
                <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-3">
                  <span className="flex items-center gap-1"><Users className="w-3.5 h-3.5" /> ~{o.qtdAlunos} alunos</span>
                  <span className="flex items-center gap-1"><MapPin className="w-3.5 h-3.5" /> {o.ambienteTipo === "sala" ? "Sala convencional" : `Outro espaço: ${o.ambienteDetalhe || "a definir"}`}</span>
                </div>
                {o.modoEquipe === "parceria" && o.colegas && <p className="text-xs text-slate-400 mt-2">Em parceria com: {o.colegas}</p>}
                {formatarMateriais(o.materiais) && <p className="text-xs text-slate-400 mt-2">Aluno leva: {formatarMateriais(o.materiais)}</p>}
                {formatarMateriais(o.materiaisNecessarios) && <p className="text-xs text-slate-400 mt-1">Materiais necessários: {formatarMateriais(o.materiaisNecessarios)}</p>}
                {o.status === "aprovada" && (
                  <div className="mt-3 pt-3 border-t border-stone-100">
                    <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Inscritos por sessão</p>
                    <div className="grid sm:grid-cols-2 gap-3">
                      {o.grupo67 && (
                        <div>
                          <p className="text-xs font-medium text-slate-600 mb-1">6º e 7º ano ({inscritos67.length}/{o.vagas67 ?? "—"})</p>
                          {inscritos67.length === 0 ? (
                            <p className="text-xs text-slate-400">Nenhum inscrito ainda.</p>
                          ) : (
                            <ul className="text-xs text-slate-600 space-y-0.5">
                              {inscritos67.map((i) => <li key={i.matricula}>{i.nomeAluno} · {i.serie} {i.turma}</li>)}
                            </ul>
                          )}
                        </div>
                      )}
                      {o.grupo89 && (
                        <div>
                          <p className="text-xs font-medium text-slate-600 mb-1">8º e 9º ano ({inscritos89.length}/{o.vagas89 ?? "—"})</p>
                          {inscritos89.length === 0 ? (
                            <p className="text-xs text-slate-400">Nenhum inscrito ainda.</p>
                          ) : (
                            <ul className="text-xs text-slate-600 space-y-0.5">
                              {inscritos89.map((i) => <li key={i.matricula}>{i.nomeAluno} · {i.serie} {i.turma}</li>)}
                            </ul>
                          )}
                        </div>
                      )}
                    </div>
                  </div>
                )}
                {o.status === "ajustes" && o.feedback && (
                  <div className="mt-2 text-xs bg-rose-50 text-rose-700 border border-rose-200 rounded-lg px-3 py-2">
                    <strong>Retorno da coordenação:</strong> {o.feedback}
                  </div>
                )}
                {(o.status === "pendente" || o.status === "ajustes") && (
                  <button
                    onClick={() => setEditing(o)}
                    className="mt-3 text-xs font-semibold text-indigo-700 hover:text-indigo-900"
                  >
                    Editar oficina
                  </button>
                )}
              </div>
              );
            })}
          </div>
        )}
      </div>
    </div>
  );
}

function MateriaisEditor({ lista, setLista, placeholderItem = "Ex.: tesoura" }) {
  function add() {
    setLista((m) => [...m, { item: "", quantidade: "" }]);
  }
  function update(i, campo, valor) {
    setLista((m) => m.map((mat, idx) => (idx === i ? { ...mat, [campo]: valor } : mat)));
  }
  function remove(i) {
    setLista((m) => m.filter((_, idx) => idx !== i));
  }
  return (
    <div className="space-y-2">
      {lista.map((mat, i) => (
        <div key={i} className="flex gap-2">
          <input
            value={mat.item}
            onChange={(e) => update(i, "item", e.target.value)}
            placeholder={placeholderItem}
            className="input flex-1"
          />
          <input
            value={mat.quantidade}
            onChange={(e) => update(i, "quantidade", e.target.value)}
            placeholder="Qtd."
            className="input shrink-0"
            style={{ width: "6rem" }}
          />
          <button type="button" onClick={() => remove(i)} className="text-rose-400 hover:text-rose-600 shrink-0"><X className="w-4 h-4" /></button>
        </div>
      ))}
      <button
        type="button"
        onClick={add}
        className="text-xs font-semibold text-indigo-700 hover:text-indigo-900 flex items-center gap-1"
      >
        <Plus className="w-3.5 h-3.5" /> Adicionar material
      </button>
    </div>
  );
}

function OficinaForm({ onSubmit, onCancel, initial, professorNome, ambientes }) {
  const [nome, setNome] = useState(initial?.nome || "");
  const [modoEquipe, setModoEquipe] = useState(initial?.modoEquipe || "sozinho");
  const [colegas, setColegas] = useState(
    initial?.colegas ? initial.colegas.split(",").map((c) => c.trim()).filter(Boolean) : []
  );
  const [qtdAlunos, setQtdAlunos] = useState(initial?.qtdAlunos || "");
  const [descricao, setDescricao] = useState(initial?.descricao || "");
  const [materiais, setMateriais] = useState(parseMateriais(initial?.materiais));
  const [materiaisNecessarios, setMateriaisNecessarios] = useState(parseMateriais(initial?.materiaisNecessarios));
  const [ambienteTipo, setAmbienteTipo] = useState(initial?.ambienteTipo || "sala");
  const [ambienteDetalhe, setAmbienteDetalhe] = useState(initial?.ambienteDetalhe || "");
  const [tituloAprovado, setTituloAprovado] = useState(initial ? !!initial.tituloAprovado : true);
  const [descricaoAprovado, setDescricaoAprovado] = useState(initial ? !!initial.descricaoAprovado : true);
  const [ambienteAprovado, setAmbienteAprovado] = useState(initial ? !!initial.ambienteAprovado : true);
  const [querOutroAmbiente, setQuerOutroAmbiente] = useState(!!initial?.ambienteSugestao);
  const [ambienteSugestao, setAmbienteSugestao] = useState(initial?.ambienteSugestao || "");
  const [salvando, setSalvando] = useState(false);

  async function enviar() {
    setSalvando(true);
    try {
      const materiaisLimpos = materiais.filter((m) => m.item.trim());
      const materiaisNecessariosLimpos = materiaisNecessarios.filter((m) => m.item.trim());
      await onSubmit({ nome: nome.trim(), modoEquipe, colegas: modoEquipe === "parceria" ? colegas.join(", ") : "", qtdAlunos: Number(qtdAlunos), descricao: descricao.trim(), materiais: JSON.stringify(materiaisLimpos), materiaisNecessarios: JSON.stringify(materiaisNecessariosLimpos), ambienteTipo, ambienteDetalhe: ambienteDetalhe.trim(), tituloAprovado, descricaoAprovado, ambienteAprovado, ambienteSugestao: ambienteAprovado ? "" : ambienteSugestao });
    } finally {
      setSalvando(false);
    }
  }

  function toggleColega(p) {
    setColegas((atual) => (atual.includes(p) ? atual.filter((c) => c !== p) : [...atual, p]));
  }

  const opcoesColegas = PROFESSORES_LISTA.filter((p) => p !== professorNome);
  const valid = nome.trim() && qtdAlunos && descricao.trim() && (modoEquipe === "sozinho" || colegas.length > 0);

  return (
    <div className="bg-white border border-stone-200 rounded-xl p-5">
      {initial && <p className="text-xs font-semibold text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-3 py-1.5 mb-4 w-fit">Clique em confirmar para cada informação solicitada. Se desejar, pode fazer alterações.</p>}
      <div className="space-y-4">
        <Field label="Nome da oficina">
          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Ex.: Slam de Poesia" className="input" />
          {initial && !initial.tituloAprovado && (
            <label className="flex items-center gap-2 mt-2 text-sm text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
              <input type="checkbox" checked={tituloAprovado} onChange={(e) => setTituloAprovado(e.target.checked)} />
              Título aprovado
            </label>
          )}
        </Field>
        <Field label="Condução da oficina">
          <div className="flex flex-col sm:flex-row gap-3">
            <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${modoEquipe === "sozinho" ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
              <input type="radio" className="hidden" checked={modoEquipe === "sozinho"} onChange={() => setModoEquipe("sozinho")} />
              Vou conduzir a oficina sozinho
            </label>
            <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${modoEquipe === "parceria" ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
              <input type="radio" className="hidden" checked={modoEquipe === "parceria"} onChange={() => setModoEquipe("parceria")} />
              Vou fazer em parceria com outros professores
            </label>
          </div>
          {modoEquipe === "parceria" && (
            <div className="flex flex-wrap gap-1.5 mt-2">
              {opcoesColegas.map((p) => (
                <button
                  type="button"
                  key={p}
                  onClick={() => toggleColega(p)}
                  className={`text-xs font-medium px-3 py-1.5 rounded-full border transition ${
                    colegas.includes(p)
                      ? "border-indigo-600 bg-indigo-600 text-white"
                      : "border-stone-300 text-slate-600 hover:border-indigo-300"
                  }`}
                >
                  {p}
                </button>
              ))}
            </div>
          )}
        </Field>
        <Field label="Quantidade estimada de alunos">
          <input type="number" min="1" value={qtdAlunos} onChange={(e) => setQtdAlunos(e.target.value)} placeholder="Mínimo: 30" className="input" />
        </Field>
        <Field label="Descrição breve da oficina">
          <textarea value={descricao} onChange={(e) => setDescricao(e.target.value)} rows={4} placeholder="Tenha em mente que esse é o resumo que o aluno lerá para se inscrever no que você está propondo." className="input resize-none" />
          {initial && !initial.descricaoAprovado && (
            <label className="flex items-center gap-2 mt-2 text-sm text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-3 py-2">
              <input type="checkbox" checked={descricaoAprovado} onChange={(e) => setDescricaoAprovado(e.target.checked)} />
              Descrição aprovada
            </label>
          )}
        </Field>
        {initial && initial.ambienteAlocado && !initial.ambienteAprovado && (
          <Field label="Ambiente definido pela coordenação">
            <p className="text-sm text-slate-600 mb-2">A coordenação reservou: <strong>{initial.ambienteAlocado}</strong></p>
            <div className="flex flex-col sm:flex-row gap-3">
              <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${ambienteAprovado ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
                <input
                  type="radio"
                  className="hidden"
                  checked={ambienteAprovado}
                  onChange={() => { setAmbienteAprovado(true); setQuerOutroAmbiente(false); setAmbienteSugestao(""); }}
                />
                Concordo com esse ambiente
              </label>
              <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${querOutroAmbiente ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
                <input
                  type="radio"
                  className="hidden"
                  checked={querOutroAmbiente}
                  onChange={() => { setQuerOutroAmbiente(true); setAmbienteAprovado(false); }}
                />
                Prefiro outro
              </label>
            </div>
            {querOutroAmbiente && (
              <select value={ambienteSugestao} onChange={(e) => setAmbienteSugestao(e.target.value)} className="input mt-2">
                <option value="">Selecione o ambiente que prefere</option>
                {initial.ambienteAlocado !== "Sala de aula convencional" && (
                  <option value="Sala de aula convencional">Sala de aula convencional</option>
                )}
                {(ambientes || [])
                  .filter((a) => a.nome !== initial.ambienteAlocado)
                  .slice()
                  .sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR"))
                  .map((a) => <option key={a.id} value={a.nome}>{a.nome}</option>)}
              </select>
            )}
          </Field>
        )}
        <Field label="Materiais que o aluno deve levar">
          <p className="text-xs text-slate-400 mb-2">Esses itens serão informados aos alunos, portanto, eles deverão trazer para oficina.</p>
          <MateriaisEditor lista={materiais} setLista={setMateriais} />
        </Field>
        <Field label="Materiais necessários">
          <p className="text-xs text-slate-400 mb-2">Itens que você precisa que a coordenação providencie para a oficina.</p>
          <MateriaisEditor lista={materiaisNecessarios} setLista={setMateriaisNecessarios} placeholderItem="Ex.: caixa de som" />
        </Field>
        {!(initial && initial.ambienteAlocado && !initial.ambienteAprovado) && (
          <Field label="Ambiente necessário">
            <div className="flex flex-col sm:flex-row gap-3">
              <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${ambienteTipo === "sala" ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
                <input type="radio" className="hidden" checked={ambienteTipo === "sala"} onChange={() => setAmbienteTipo("sala")} />
                Sala de aula convencional
              </label>
              <label className={`flex-1 flex items-center gap-2 border rounded-lg px-3 py-2.5 cursor-pointer text-sm ${ambienteTipo === "outro" ? "border-indigo-600 bg-indigo-50 text-indigo-900 font-semibold" : "border-stone-300 text-slate-500"}`}>
                <input type="radio" className="hidden" checked={ambienteTipo === "outro"} onChange={() => setAmbienteTipo("outro")} />
                Outro espaço da escola
              </label>
            </div>
            {ambienteTipo === "outro" && (
              <select value={ambienteDetalhe} onChange={(e) => setAmbienteDetalhe(e.target.value)} className="input mt-2">
                <option value="">Selecione o espaço</option>
                {(ambientes || []).slice().sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR")).map((a) => <option key={a.id} value={a.nome}>{a.nome}</option>)}
              </select>
            )}
          </Field>
        )}
      </div>
      <div className="flex gap-2 mt-5">
        {initial && <button onClick={onCancel} className="px-4 py-2.5 rounded-lg text-sm font-semibold text-slate-500 border border-stone-300">Cancelar</button>}
        <button
          disabled={!valid || salvando}
          onClick={enviar}
          className="flex-1 flex items-center justify-center gap-2 bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
        >
          <Plus className="w-4 h-4" /> {salvando ? "Salvando…" : initial ? "Reenviar oficina" : "Cadastrar oficina"}
        </button>
      </div>
      <style>{`.input { width:100%; border:1px solid #d6d3d1; border-radius:0.5rem; padding:0.6rem 0.9rem; font-size:0.9rem; } .input:focus { outline:none; box-shadow:0 0 0 2px #fbbf24; }`}</style>
    </div>
  );
}

function Field({ label, children }) {
  return (
    <div>
      <label className="block text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">{label}</label>
      {children}
    </div>
  );
}

/* ---------------- ADMIN ---------------- */
const SENHA_COORDENACAO = "Arena@123!";

function AdminLogin({ onBack, onUnlock }) {
  const [senha, setSenha] = useState("");
  const [erro, setErro] = useState("");

  function entrar() {
    if (senha === SENHA_COORDENACAO) {
      onUnlock();
    } else {
      setErro("Senha incorreta.");
    }
  }

  return (
    <div>
      <BackBar onBack={onBack} title="Área restrita" tone="dark" />
      <div className="max-w-sm mx-auto px-6 py-16 text-center">
        <ShieldCheck className="w-10 h-10 mx-auto text-indigo-700 mb-3" />
        <p className="text-slate-600 mb-4">Acesso da coordenação. Informe a senha para continuar.</p>
        <input
          type="password"
          value={senha}
          onChange={(e) => { setSenha(e.target.value); setErro(""); }}
          onKeyDown={(e) => e.key === "Enter" && entrar()}
          placeholder="Senha"
          autoFocus
          className="input mb-3"
        />
        {erro && <p className="text-rose-600 text-sm mb-3">{erro}</p>}
        <button
          disabled={!senha}
          onClick={entrar}
          className="w-full bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
        >
          Entrar
        </button>
        <style>{`.input { width:100%; border:1px solid #d6d3d1; border-radius:0.5rem; padding:0.6rem 0.9rem; font-size:0.9rem; } .input:focus { outline:none; box-shadow:0 0 0 2px #fbbf24; }`}</style>
      </div>
    </div>
  );
}

function AdminPortal({ onBack, oficinas, saveOficinas, ambientes, saveAmbientes, inscricoes, saveInscricoes, vagasOcupadas, flash }) {
  const [tab, setTab] = useState("dashboard");
  const [filtro, setFiltro] = useState("pendentes");
  // Com mais de mil inscritos, não faz sentido montar todos os comprovantes
  // na tela (nem ficaria visível, nem seria rápido) — eles só são gerados,
  // fora da tela, na hora de imprimir, e um série por vez.
  const [serieImprimindo, setSerieImprimindo] = useState(null);
  useEffect(() => {
    if (serieImprimindo) {
      imprimirSecao("comprovantes-imprimivel");
      setSerieImprimindo(null);
    }
  }, [serieImprimindo]);

  const oficinasPendentes = oficinas.filter(precisaConfirmacaoDoProfessor);
  const oficinasConfirmadas = oficinas.filter((o) => !precisaConfirmacaoDoProfessor(o));
  const oficinasFiltradas = filtro === "pendentes" ? oficinasPendentes : oficinasConfirmadas;

  // Conflito de sala só existe dentro da MESMA sessão (6º/7º e 8º/9º
  // acontecem em horários diferentes, então a mesma sala serve as duas
  // sem problema) — por isso a contagem é separada por grupo.
  const alocacaoCount67 = {};
  const alocacaoCount89 = {};
  oficinas.forEach((o) => {
    if (o.status === "aprovada" && o.ambienteAlocado) {
      if (o.grupo67) alocacaoCount67[o.ambienteAlocado] = (alocacaoCount67[o.ambienteAlocado] || 0) + 1;
      if (o.grupo89) alocacaoCount89[o.ambienteAlocado] = (alocacaoCount89[o.ambienteAlocado] || 0) + 1;
    }
  });

  function updateOficina(id, changes) {
    saveOficinas(oficinas.map((o) => (o.id === id ? { ...o, ...changes } : o)));
  }

  function removerOficina(id) {
    if (!confirm("Remover esta oficina definitivamente? Inscrições vinculadas continuarão salvas, mas a oficina some do catálogo.")) return;
    saveOficinas(oficinas.filter((o) => o.id !== id));
  }


  return (
    <div>
      <BackBar onBack={onBack} title="Coordenação — LiterArena" tone="dark" />
      <div className="max-w-4xl mx-auto px-5 py-6">
        <div className="flex gap-1 mb-6 bg-stone-100 p-1 rounded-lg w-fit overflow-x-auto">
          {[["dashboard", "Dashboard"], ["oficinas", "Oficinas"], ["ambientes", "Ambientes"], ["relatorios", "Relatórios"]].map(([k, l]) => (
            <button key={k} onClick={() => setTab(k)} className={`px-4 py-1.5 rounded-md text-sm font-semibold whitespace-nowrap ${tab === k ? "bg-white shadow text-indigo-950" : "text-slate-500"}`}>{l}</button>
          ))}
        </div>

        {tab === "dashboard" && (
          <div>
            <div className="grid grid-cols-2 sm:grid-cols-3 gap-3 mb-6">
              <Stat icon={BookOpen} label="Oficinas" value={oficinas.length} />
              <Stat icon={GraduationCap} label="Professores" value={new Set(oficinas.map((o) => o.professor.toLowerCase())).size} />
              <Stat icon={Users} label="Alunos inscritos" value={inscricoes.length} />
              <Stat icon={Ticket} label="Vagas · 6º e 7º ano" value={oficinas.reduce((soma, o) => soma + (o.grupo67 ? (o.vagas67 || 0) : 0), 0)} />
              <Stat icon={Ticket} label="Vagas · 8º e 9º ano" value={oficinas.reduce((soma, o) => soma + (o.grupo89 ? (o.vagas89 || 0) : 0), 0)} />
              <Stat icon={School} label="Ambientes" value={ambientes.length} />
            </div>
          </div>
        )}

        {tab === "oficinas" && (
          <div>
            <div className="flex gap-1 mb-4 bg-stone-100 p-1 rounded-lg w-fit overflow-x-auto">
              <button onClick={() => setFiltro("pendentes")} className={`px-4 py-1.5 rounded-md text-sm font-semibold whitespace-nowrap ${filtro === "pendentes" ? "bg-white shadow text-indigo-950" : "text-slate-500"}`}>
                Pendentes ({oficinasPendentes.length})
              </button>
              <button onClick={() => setFiltro("confirmadas")} className={`px-4 py-1.5 rounded-md text-sm font-semibold whitespace-nowrap ${filtro === "confirmadas" ? "bg-white shadow text-indigo-950" : "text-slate-500"}`}>
                Confirmadas ({oficinasConfirmadas.length})
              </button>
              <button onClick={() => setFiltro("cadastrar")} className={`px-4 py-1.5 rounded-md text-sm font-semibold whitespace-nowrap ${filtro === "cadastrar" ? "bg-white shadow text-indigo-950" : "text-slate-500"}`}>
                Cadastrar
              </button>
            </div>

            {filtro === "cadastrar" ? (
              <AdminCriarOficina saveOficinas={saveOficinas} oficinas={oficinas} ambientes={ambientes} flash={flash} />
            ) : (
              <div className="space-y-3">
                {oficinasFiltradas.map((o) => (
                  <AdminOficinaRow key={o.id} oficina={o} ambientes={ambientes} ocupadas67={vagasOcupadas(o.id, "67")} ocupadas89={vagasOcupadas(o.id, "89")} alocacaoCount67={alocacaoCount67} alocacaoCount89={alocacaoCount89} onUpdate={updateOficina} onRemove={removerOficina} />
                ))}
                {oficinasFiltradas.length === 0 && (
                  <p className="text-sm text-slate-400 text-center py-10">
                    {filtro === "pendentes" ? "Nenhuma oficina aguardando confirmação do professor." : "Nenhuma oficina confirmada ainda."}
                  </p>
                )}
              </div>
            )}
          </div>
        )}

        {tab === "ambientes" && <AmbientesManager ambientes={ambientes} saveAmbientes={saveAmbientes} oficinas={oficinas} />}

        {tab === "relatorios" && (
          <div className="space-y-4">
            <h3 className="font-serif font-bold text-indigo-950">Relatório de inscrições por oficina</h3>
            <div className="space-y-2">
              {oficinas.filter((o) => o.status === "aprovada").map((o) => (
                <div key={o.id} className="border border-stone-200 rounded-lg p-3 bg-white space-y-2">
                  <div className="text-sm font-semibold">{o.nome} <span className="text-slate-400 font-normal">· {o.professor}</span></div>
                  {o.grupo67 && <BarraVagas label="6º e 7º ano" ocupadas={vagasOcupadas(o.id, "67")} vagas={o.vagas67} />}
                  {o.grupo89 && <BarraVagas label="8º e 9º ano" ocupadas={vagasOcupadas(o.id, "89")} vagas={o.vagas89} />}
                </div>
              ))}
              {oficinas.filter((o) => o.status === "aprovada").length === 0 && <p className="text-sm text-slate-400">Nenhuma oficina aprovada ainda.</p>}
            </div>

            <div className="mt-8 mb-2">
              <h3 className="font-serif font-bold text-indigo-950">Relatório de materiais necessários</h3>
              <p className="text-xs text-slate-500 mt-0.5">Não fica na tela — clique para gerar e imprimir.</p>
            </div>
            <button onClick={() => imprimirSecao("relatorio-materiais-imprimivel")} className="text-xs font-semibold bg-indigo-950 text-white px-3 py-1.5 rounded-lg flex items-center gap-1"><Printer className="w-3.5 h-3.5" /> Imprimir materiais necessários</button>
            <div id="relatorio-materiais-imprimivel" data-print-secao className="print-secao-fora-da-tela space-y-2">
              {oficinas.filter((o) => parseMateriais(o.materiaisNecessarios).some((m) => m.item?.trim())).map((o) => (
                <div key={o.id} className="border border-stone-200 rounded-lg p-3 bg-white">
                  <div className="flex items-center gap-2 text-sm font-semibold text-indigo-950">
                    {o.nome} <span className="text-slate-400 font-normal">· {o.professor}</span> <StatusBadge status={o.status} />
                  </div>
                  <ul className="mt-1.5 text-sm text-slate-600 list-disc list-inside">
                    {parseMateriais(o.materiaisNecessarios).filter((m) => m.item?.trim()).map((m, i) => (
                      <li key={i}>{m.quantidade?.trim() ? `${m.quantidade} ` : ""}{m.item}</li>
                    ))}
                  </ul>
                </div>
              ))}
              {oficinas.filter((o) => parseMateriais(o.materiaisNecessarios).some((m) => m.item?.trim())).length === 0 && (
                <p className="text-sm text-slate-400">Nenhum professor informou materiais necessários ainda.</p>
              )}
            </div>

            <div className="mt-8 mb-2">
              <h3 className="font-serif font-bold text-indigo-950">Comprovantes de inscrição</h3>
              <p className="text-xs text-slate-500 mt-0.5">Com {inscricoes.length} inscritos, os comprovantes não ficam na tela — escolha uma série para gerar e imprimir só os dela.</p>
            </div>
            <div className="flex flex-wrap gap-2">
              {SERIES.map((s) => {
                const qtd = inscricoes.filter((i) => i.serie === s).length;
                return (
                  <button
                    key={s}
                    disabled={qtd === 0 || !!serieImprimindo}
                    onClick={() => setSerieImprimindo(s)}
                    className="text-xs font-semibold bg-indigo-950 disabled:opacity-40 text-white px-3 py-1.5 rounded-lg flex items-center gap-1"
                  >
                    <Printer className="w-3.5 h-3.5" /> {serieImprimindo === s ? "Gerando…" : `${s} (${qtd})`}
                  </button>
                );
              })}
            </div>
            <div id="comprovantes-imprimivel" data-print-secao className="print-secao-fora-da-tela space-y-4">
              {serieImprimindo && inscricoes.filter((i) => i.serie === serieImprimindo).map((i) => (
                <div key={i.matricula} className="comprovante-print-item">
                  <ComprovanteCard inscricao={i} oficina={oficinas.find((o) => o.id === i.oficinaId)} />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>
      <style>{`
        .input { width:100%; border:1px solid #d6d3d1; border-radius:0.5rem; padding:0.6rem 0.9rem; font-size:0.9rem; }
        .input:focus { outline:none; box-shadow:0 0 0 2px #fbbf24; }
        .print-secao-fora-da-tela { position: absolute; left: -99999px; top: 0; }
        @media print {
          body * { visibility: hidden; }
          [data-print-ativo], [data-print-ativo] * { visibility: visible; }
          [data-print-ativo] { position: absolute !important; left: 0 !important; top: 0 !important; width: 100%; }
          .comprovante-print-item { page-break-after: always; }
        }
      `}</style>
    </div>
  );
}

function Stat({ icon: Icon, label, value }) {
  return (
    <div className="bg-white border border-stone-200 rounded-xl p-4">
      <Icon className="w-4 h-4 text-indigo-700 mb-2" />
      <div className="text-2xl font-bold text-indigo-950">{value}</div>
      <div className="text-xs text-slate-500">{label}</div>
    </div>
  );
}

function BarraVagas({ label, ocupadas, vagas }) {
  const pct = vagas ? Math.min(100, Math.round((ocupadas / vagas) * 100)) : 0;
  return (
    <div>
      <div className="flex justify-between text-xs text-slate-500 mb-1"><span>{label}</span><span>{ocupadas}/{vagas ?? "—"}</span></div>
      <div className="h-2 bg-stone-100 rounded-full overflow-hidden"><div className="h-full bg-amber-400" style={{ width: `${pct}%` }} /></div>
    </div>
  );
}

function AdminCriarOficina({ saveOficinas, oficinas, ambientes, flash }) {
  const [professor, setProfessor] = useState("");
  const [nome, setNome] = useState("");
  const [descricao, setDescricao] = useState("");
  const [vagas, setVagas] = useState("");
  const [ambienteAlocado, setAmbienteAlocado] = useState("");
  const [salvando, setSalvando] = useState(false);

  const valid = professor && nome.trim() && descricao.trim();

  async function criar() {
    setSalvando(true);
    try {
      const vagasNum = Number(vagas) || 0;
      const ok = await saveOficinas([
        ...oficinas,
        {
          id: uid(),
          professor,
          nome: nome.trim(),
          descricao: descricao.trim(),
          modoEquipe: "sozinho",
          colegas: "",
          qtdAlunos: vagasNum,
          materiais: "[]",
          materiaisNecessarios: "[]",
          ambienteTipo: "sala",
          ambienteDetalhe: "",
          status: "pendente",
          vagas: vagasNum || null,
          vagas67: vagasNum || null,
          vagas89: vagasNum || null,
          grupo67: true,
          grupo89: true,
          ambienteAlocado,
          feedback: "",
          tituloAprovado: false,
          descricaoAprovado: false,
          ambienteAprovado: !ambienteAlocado,
          ambienteSugestao: "",
          createdAt: Date.now(),
        },
      ]);
      if (ok) {
        flash(`Oficina cadastrada para ${professor}. Quando ele/ela logar, vai confirmar título, descrição${ambienteAlocado ? " e ambiente" : ""}, e completar os detalhes.`);
        setProfessor("");
        setNome("");
        setDescricao("");
        setVagas("");
        setAmbienteAlocado("");
      }
    } finally {
      setSalvando(false);
    }
  }

  return (
    <div className="bg-white border border-stone-200 rounded-xl p-4 mb-4">
      <h3 className="font-serif font-bold text-indigo-950 mb-3">Cadastrar oficina manualmente</h3>
      <div className="space-y-3">
        <Field label="Professor">
          <select value={professor} onChange={(e) => setProfessor(e.target.value)} className="input">
            <option value="">Selecione…</option>
            {PROFESSORES_LISTA.map((p) => <option key={p} value={p}>{p}</option>)}
          </select>
        </Field>
        <Field label="Título da oficina">
          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Ex.: Slam de Poesia" className="input" />
        </Field>
        <Field label="Descrição">
          <textarea value={descricao} onChange={(e) => setDescricao(e.target.value)} rows={6} className="input" />
        </Field>
        <div className="flex gap-3">
          <Field label="Vagas">
            <input type="number" min="0" value={vagas} onChange={(e) => setVagas(e.target.value)} placeholder="Ex.: 30" className="input" />
          </Field>
          <Field label="Ambiente">
            <select value={ambienteAlocado} onChange={(e) => setAmbienteAlocado(e.target.value)} className="input">
              <option value="">Selecione…</option>
              <option value="Sala de aula convencional">Sala de aula convencional</option>
              {(ambientes || []).slice().sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR")).map((a) => <option key={a.id} value={a.nome}>{a.nome}</option>)}
            </select>
          </Field>
        </div>
      </div>
      <button
        disabled={!valid || salvando}
        onClick={criar}
        className="mt-3 text-sm font-semibold bg-indigo-950 disabled:opacity-40 text-white px-4 py-2 rounded-lg flex items-center gap-1"
      >
        <Plus className="w-4 h-4" /> {salvando ? "Cadastrando…" : "Cadastrar oficina"}
      </button>
    </div>
  );
}

function AdminOficinaRow({ oficina, ambientes, ocupadas67, ocupadas89, alocacaoCount67, alocacaoCount89, onUpdate, onRemove }) {
  const [nome, setNome] = useState(oficina.nome);
  const [descricao, setDescricao] = useState(oficina.descricao);
  const [grupo67, setGrupo67] = useState(oficina.grupo67);
  const [grupo89, setGrupo89] = useState(oficina.grupo89);
  const [vagas67, setVagas67] = useState(oficina.vagas67);
  const [vagas89, setVagas89] = useState(oficina.vagas89);
  const [ambienteAlocado, setAmbienteAlocado] = useState(oficina.ambienteAlocado || "");

  const mesmoAmbienteAtual = ambienteAlocado === oficina.ambienteAlocado && oficina.status === "aprovada";
  const outrasNesseAmbiente67 = mesmoAmbienteAtual && oficina.grupo67
    ? (alocacaoCount67[ambienteAlocado] || 0) - 1
    : (alocacaoCount67[ambienteAlocado] || 0);
  const outrasNesseAmbiente89 = mesmoAmbienteAtual && oficina.grupo89
    ? (alocacaoCount89[ambienteAlocado] || 0) - 1
    : (alocacaoCount89[ambienteAlocado] || 0);
  // "Sala de aula convencional" não é um espaço único (a escola tem várias
  // salas comuns) — nunca é conflito. E como as sessões do 6º/7º e do
  // 8º/9º ano acontecem em horários diferentes, só é conflito de verdade
  // quando outra oficina usa a mesma sala NA MESMA sessão.
  const ehSalaEspecifica = ambienteAlocado && ambienteAlocado !== "Sala de aula convencional";
  const conflito67 = ehSalaEspecifica && grupo67 && outrasNesseAmbiente67 > 0;
  const conflito89 = ehSalaEspecifica && grupo89 && outrasNesseAmbiente89 > 0;
  const conflito = conflito67 || conflito89;
  const editValido = nome.trim() && descricao.trim();
  const ambientePendente = oficina.ambienteAlocado && !oficina.ambienteAprovado;
  const aguardandoConfirmacao = precisaConfirmacaoDoProfessor(oficina);

  function salvarTexto(changes) {
    const mudouAmbiente = "ambienteAlocado" in changes && changes.ambienteAlocado !== oficina.ambienteAlocado;
    onUpdate(oficina.id, {
      nome: nome.trim(),
      descricao: descricao.trim(),
      ...changes,
      ...(changes.status === "aprovada"
        ? { ambienteAprovado: true }
        : mudouAmbiente
        ? { ambienteAprovado: false, ambienteSugestao: "" }
        : {}),
    });
  }

  return (
    <div className="border border-stone-200 rounded-xl p-4 bg-white">
      <div className="flex items-start justify-between gap-3">
        <p className="text-xs text-slate-400">{oficina.professor}</p>
        {oficina.status === "pendente" && !aguardandoConfirmacao ? (
          <span className="inline-flex items-center gap-1 text-xs font-bold px-2.5 py-1 rounded-full border bg-blue-100 text-blue-800 border-blue-300 shrink-0 whitespace-nowrap">
            <CheckCircle2 className="w-3.5 h-3.5" /> Confirmada pelo professor
          </span>
        ) : (
          <StatusBadge status={oficina.status} />
        )}
      </div>

      <div className="space-y-2 mt-2">
        <Field label="Título da oficina">
          <input value={nome} onChange={(e) => setNome(e.target.value)} className="input font-serif font-bold" />
        </Field>
        <Field label="Descrição">
          <textarea value={descricao} onChange={(e) => setDescricao(e.target.value)} rows={6} className="input" />
        </Field>
      </div>

      {aguardandoConfirmacao && (
        <p className="text-xs text-amber-700 bg-amber-50 border border-amber-200 rounded-lg px-3 py-1.5 mt-2 flex items-center gap-1 w-fit">
          <AlertTriangle className="w-3.5 h-3.5" /> Aguardando o professor confirmar: {[!oficina.tituloAprovado && "título", !oficina.descricaoAprovado && "descrição", ambientePendente && "ambiente"].filter(Boolean).join(", ")}.
          {oficina.ambienteSugestao && <> O professor prefere: <strong>{oficina.ambienteSugestao}</strong>.</>}
        </p>
      )}

      <div className="flex flex-wrap gap-4 text-xs text-slate-500 mt-3">
        <span>~{oficina.qtdAlunos} alunos estimados · {ocupadas67 + ocupadas89} inscritos</span>
        <span>{oficina.ambienteTipo === "sala" ? "Sala convencional" : `Outro: ${oficina.ambienteDetalhe || "—"}`}</span>
        {formatarMateriais(oficina.materiais) && <span>Aluno leva: {formatarMateriais(oficina.materiais)}</span>}
        {formatarMateriais(oficina.materiaisNecessarios) && <span>Materiais necessários: {formatarMateriais(oficina.materiaisNecessarios)}</span>}
        {oficina.modoEquipe === "parceria" && oficina.colegas && <span>Em parceria com: {oficina.colegas}</span>}
      </div>

      <div className="mt-3">
        <p className="text-xs font-semibold text-slate-500 uppercase tracking-wide mb-1.5">Sessões e vagas (vagas independentes por sessão)</p>
        <div className="grid sm:grid-cols-2 gap-2">
          <div className={`border rounded-lg p-2.5 ${grupo67 ? "border-stone-300" : "border-stone-200 opacity-60"}`}>
            <label className="flex items-center gap-2 text-sm font-medium cursor-pointer">
              <input type="checkbox" checked={grupo67} onChange={(e) => setGrupo67(e.target.checked)} />
              6º e 7º ano
            </label>
            {grupo67 && (
              <div className="mt-1.5 flex items-center gap-2">
                <input type="number" min="0" value={vagas67 ?? ""} onChange={(e) => setVagas67(Number(e.target.value))} className="input" style={{ width: "5rem" }} />
                <span className="text-xs text-slate-500">vagas · {ocupadas67} inscritos</span>
              </div>
            )}
          </div>
          <div className={`border rounded-lg p-2.5 ${grupo89 ? "border-stone-300" : "border-stone-200 opacity-60"}`}>
            <label className="flex items-center gap-2 text-sm font-medium cursor-pointer">
              <input type="checkbox" checked={grupo89} onChange={(e) => setGrupo89(e.target.checked)} />
              8º e 9º ano
            </label>
            {grupo89 && (
              <div className="mt-1.5 flex items-center gap-2">
                <input type="number" min="0" value={vagas89 ?? ""} onChange={(e) => setVagas89(Number(e.target.value))} className="input" style={{ width: "5rem" }} />
                <span className="text-xs text-slate-500">vagas · {ocupadas89} inscritos</span>
              </div>
            )}
          </div>
        </div>
      </div>

      <div className="mt-3">
        <Field label="Ambiente alocado">
          <select
            value={ambienteAlocado}
            onChange={(e) => setAmbienteAlocado(e.target.value)}
            className={`input ${conflito ? "border-rose-400 focus:ring-rose-400" : ""}`}
          >
            <option value="">A definir</option>
            <option value="Sala de aula convencional">Sala de aula convencional</option>
            {ambientes.slice().sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR")).map((a) => <option key={a.id} value={a.nome}>{a.nome}</option>)}
          </select>
          {conflito && (
            <p className="text-xs text-rose-600 font-semibold mt-1 flex items-center gap-1">
              <AlertTriangle className="w-3.5 h-3.5" /> Esse espaço já foi alocado para outra oficina aprovada {conflito67 && conflito89 ? "nas duas sessões" : conflito67 ? "na sessão do 6º/7º ano" : "na sessão do 8º/9º ano"}.
            </p>
          )}
        </Field>
      </div>

      <div className="flex flex-wrap gap-2 mt-3">
        <button disabled={!editValido || aguardandoConfirmacao} title={aguardandoConfirmacao ? "O professor ainda não confirmou título, descrição e/ou ambiente" : ""} onClick={() => salvarTexto({ status: "aprovada", grupo67, grupo89, vagas67, vagas89, ambienteAlocado, feedback: "" })} className="text-xs font-semibold bg-emerald-600 hover:bg-emerald-700 disabled:opacity-40 text-white px-3 py-1.5 rounded-lg">Aprovar</button>
        <button disabled={!editValido} onClick={() => salvarTexto({ grupo67, grupo89, vagas67, vagas89, ambienteAlocado })} className="text-xs font-semibold border border-stone-300 disabled:opacity-40 text-slate-600 px-3 py-1.5 rounded-lg">Salvar alterações</button>
        <button onClick={() => onRemove(oficina.id)} className="text-xs font-semibold text-rose-500 px-3 py-1.5 rounded-lg ml-auto flex items-center gap-1"><Trash2 className="w-3.5 h-3.5" /> Remover</button>
      </div>
    </div>
  );
}

function AmbientesManager({ ambientes, saveAmbientes, oficinas }) {
  const [nome, setNome] = useState("");
  const [tipo, setTipo] = useState("sala");

  function add() {
    if (!nome.trim()) return;
    saveAmbientes([...ambientes, { id: uid(), nome: nome.trim(), capacidade: 0, tipo }]);
    setNome("");
  }

  const faltando = DEFAULT_AMBIENTES.filter(
    (d) => !ambientes.some((a) => a.nome.trim().toLowerCase() === d.nome.trim().toLowerCase())
  );

  function completarPadrao() {
    saveAmbientes([...ambientes, ...faltando.map((d) => ({ ...d, id: uid() }))]);
  }

  return (
    <div>
      {faltando.length > 0 && (
        <div className="bg-amber-50 border border-amber-200 rounded-xl p-4 mb-4 flex items-center justify-between gap-3 flex-wrap">
          <p className="text-sm text-amber-800">Faltam {faltando.length} espaços da lista padrão da escola ({faltando.map((f) => f.nome).join(", ")}).</p>
          <button onClick={completarPadrao} className="text-xs font-semibold bg-amber-400 hover:bg-amber-300 text-indigo-950 px-3 py-2 rounded-lg whitespace-nowrap">Adicionar espaços padrão</button>
        </div>
      )}
      <div className="bg-white border border-stone-200 rounded-xl p-4 mb-4">
        <h3 className="font-serif font-bold text-indigo-950 mb-3">Cadastrar ambiente</h3>
        <div className="grid sm:grid-cols-3 gap-2">
          <input value={nome} onChange={(e) => setNome(e.target.value)} placeholder="Nome (ex.: Biblioteca)" className="input sm:col-span-2" />
          <select value={tipo} onChange={(e) => setTipo(e.target.value)} className="input">
            <option value="sala">Sala convencional</option>
            <option value="outro">Outro espaço</option>
          </select>
        </div>
        <button onClick={add} className="mt-3 text-sm font-semibold bg-indigo-950 text-white px-4 py-2 rounded-lg flex items-center gap-1"><Plus className="w-4 h-4" /> Adicionar</button>
      </div>
      <div className="space-y-2">
        {ambientes.slice().sort((a, b) => a.nome.localeCompare(b.nome, "pt-BR")).map((a) => (
          <AmbienteRow
            key={a.id}
            ambiente={a}
            ambientes={ambientes}
            saveAmbientes={saveAmbientes}
            oficinasDoAmbiente={oficinas.filter((o) => o.ambienteAlocado === a.nome)}
          />
        ))}
        {ambientes.length === 0 && <p className="text-sm text-slate-400">Nenhum ambiente cadastrado ainda.</p>}
      </div>
    </div>
  );
}

function AmbienteRow({ ambiente, ambientes, saveAmbientes, oficinasDoAmbiente }) {
  return (
    <div className="border border-stone-200 rounded-lg px-4 py-2.5 bg-white text-sm">
      <div className="flex items-center justify-between gap-3">
        <span className="font-medium">{ambiente.nome} <span className="text-slate-400 font-normal">· {ambiente.tipo === "sala" ? "sala convencional" : "outro espaço"}</span></span>
        <button onClick={() => saveAmbientes(ambientes.filter((x) => x.id !== ambiente.id))} className="text-rose-400 hover:text-rose-600 shrink-0"><X className="w-4 h-4" /></button>
      </div>
      {oficinasDoAmbiente.length > 0 ? (
        <ul className="mt-1.5 space-y-1">
          {oficinasDoAmbiente.map((o) => (
            <li key={o.id} className="text-xs text-slate-500 flex items-center gap-1.5">
              <span className="font-medium text-slate-700">{o.nome}</span> · {o.professor}
              <StatusBadge status={o.status} />
            </li>
          ))}
        </ul>
      ) : (
        <p className="mt-1 text-xs text-slate-400">Nenhuma oficina usando este ambiente.</p>
      )}
    </div>
  );
}

/* ---------------- ALUNO ---------------- */
function AlunoPortal({ onBack, oficinas, inscricoes, saveInscricoes, vagasOcupadas, flash }) {
  const [matricula, setMatricula] = useState("");
  const [nomeAluno, setNomeAluno] = useState("");
  const [serie, setSerie] = useState("");
  const [turma, setTurma] = useState("");
  const [identificado, setIdentificado] = useState(false);
  const [processando, setProcessando] = useState(false);

  const minhaInscricao = useMemo(
    () => inscricoes.find((i) => i.matricula === matricula),
    [inscricoes, matricula]
  );

  if (!identificado) {
    return (
      <div>
        <BackBar onBack={onBack} title="Portal do Aluno" />
        <div className="max-w-sm mx-auto px-6 py-16 text-center">
          <Ticket className="w-10 h-10 mx-auto text-indigo-700 mb-3" />
          <p className="text-slate-600 mb-4">Informe seus dados para escolher sua oficina.</p>
          <input value={matricula} onChange={(e) => setMatricula(e.target.value.trim())} placeholder="Número de matrícula" className="input mb-3" />
          <input value={nomeAluno} onChange={(e) => setNomeAluno(e.target.value)} placeholder="Seu nome completo" className="input mb-3" />
          <div className="flex gap-3 mb-3">
            <select value={serie} onChange={(e) => setSerie(e.target.value)} className="input">
              <option value="">Série</option>
              {SERIES.map((s) => <option key={s} value={s}>{s}</option>)}
            </select>
            <select value={turma} onChange={(e) => setTurma(e.target.value)} className="input">
              <option value="">Turma</option>
              {TURMAS.map((t) => <option key={t} value={t}>{t}</option>)}
            </select>
          </div>
          <button
            disabled={!matricula || !nomeAluno.trim() || !serie || !turma.trim()}
            onClick={() => setIdentificado(true)}
            className="w-full bg-indigo-950 disabled:opacity-40 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
          >
            Continuar
          </button>
          <style>{`.input { width:100%; border:1px solid #d6d3d1; border-radius:0.5rem; padding:0.6rem 0.9rem; font-size:0.9rem; } .input:focus { outline:none; box-shadow:0 0 0 2px #fbbf24; }`}</style>
        </div>
      </div>
    );
  }

  const meuGrupo = grupoPorSerie(serie);
  const disponiveis = oficinas.filter((o) => o.status === "aprovada" && (meuGrupo === "67" ? o.grupo67 : o.grupo89));

  if (minhaInscricao) {
    const oficina = oficinas.find((o) => o.id === minhaInscricao.oficinaId);
    return (
      <div>
        <BackBar onBack={onBack} title="Minha Inscrição" />
        <div className="max-w-md mx-auto px-6 py-10">
          <ComprovanteCard id="comprovante-imprimivel" inscricao={minhaInscricao} oficina={oficina} />
          <button
            onClick={() => window.print()}
            className="w-full mt-4 flex items-center justify-center gap-2 bg-indigo-950 text-white font-semibold py-2.5 rounded-lg hover:bg-indigo-900"
          >
            <Printer className="w-4 h-4" /> Imprimir ou salvar em PDF
          </button>
          <button
            disabled={processando}
            onClick={async () => {
              setProcessando(true);
              const ok = await saveInscricoes(inscricoes.filter((i) => i.matricula !== matricula));
              setProcessando(false);
              if (ok) flash("Inscrição cancelada. Você pode escolher outra oficina.");
            }}
            className="w-full mt-4 flex items-center justify-center gap-2 bg-rose-600 text-white font-semibold py-2.5 rounded-lg hover:bg-rose-700 disabled:opacity-40"
          >
            <X className="w-4 h-4" /> {processando ? "Cancelando…" : "Cancelar e escolher outra oficina"}
          </button>
          <style>{`
            @media print {
              body * { visibility: hidden; }
              #comprovante-imprimivel, #comprovante-imprimivel * { visibility: visible; }
              #comprovante-imprimivel { position: absolute; left: 0; top: 0; width: 100%; }
            }
          `}</style>
        </div>
      </div>
    );
  }

  return (
    <div>
      <BackBar onBack={onBack} title="Escolher Oficina" />
      <div className="max-w-2xl mx-auto px-5 py-6">
        <p className="text-sm text-slate-500 mb-4">Olá, <span className="font-semibold">{nomeAluno}</span> — escolha <strong>uma</strong> oficina para o dia 23 de outubro (manhã). Depois de confirmar, não será possível escolher outra sem cancelar antes.</p>
        <div className="space-y-3">
          {disponiveis.map((o) => {
            const vagasGrupo = meuGrupo === "67" ? o.vagas67 : o.vagas89;
            const ocupadas = vagasOcupadas(o.id, meuGrupo);
            const cheia = ocupadas >= vagasGrupo;
            return (
              <div key={o.id} className="border border-stone-200 rounded-xl p-4 bg-white flex items-start justify-between gap-4">
                <div>
                  <h3 className="font-serif font-bold text-indigo-950">{o.nome}</h3>
                  <p className="text-sm text-slate-500">{o.descricao}</p>
                  <div className="flex gap-3 text-xs text-slate-400 mt-2">
                    <span>{o.professor}</span>
                    <span>{o.ambienteTipo === "sala" ? "Sala convencional" : o.ambienteDetalhe || "Outro espaço"}</span>
                    <span className={cheia ? "text-rose-500 font-semibold" : ""}>{ocupadas}/{vagasGrupo} vagas</span>
                  </div>
                </div>
                <button
                  disabled={cheia || processando}
                  onClick={async () => {
                    if (!confirm(`Tem certeza que quer se inscrever em "${o.nome}"? Não será possível alterar depois sem cancelar antes.`)) return;
                    setProcessando(true);
                    const ok = await saveInscricoes([...inscricoes, { matricula, nomeAluno: nomeAluno.trim(), serie, turma: turma.trim(), oficinaId: o.id, timestamp: Date.now() }]);
                    setProcessando(false);
                    if (ok) flash("Inscrição confirmada!");
                  }}
                  className="shrink-0 text-xs font-semibold bg-amber-400 hover:bg-amber-300 disabled:opacity-30 disabled:hover:bg-amber-400 text-indigo-950 px-4 py-2 rounded-lg"
                >
                  {cheia ? "Lotada" : processando ? "Enviando…" : "Escolher"}
                </button>
              </div>
            );
          })}
          {disponiveis.length === 0 && <p className="text-sm text-slate-400 text-center py-10">Nenhuma oficina aprovada disponível ainda. Volte mais tarde.</p>}
        </div>
      </div>
    </div>
  );
}
